-- 신조어 13개 추가 (2026-09-08 아침 검수, 운영자 승인).
-- 후보 테이블(slang_candidates)에서 승격한 11개: 답정너·소확행·딸깍·누칼협·알빠노·무지성·손민수·킹정·국뽕·드렁슨·진지스칸.
-- 후보에 없던 2개는 운영자 지시로 이 세션에서 직접 작성했다:
--   쉬었음 청년 — 통계청 경제활동인구조사의 '쉬었음' 분류에서 나온 사회 신조어. 구직 활동을 한
--     '실업자'와 통계상 구분되는 점을 정의와 용법에 명시했다.
--   위고빔 — 유튜브 《빠더너스》 문상훈이 2025년 '유행할 신조어 예측' 영상에서 만든 창작 신조어.
--     자연 발생어가 아니라는 점을 origin에 명시했다.
-- 뜻이 갈리던 항목의 처리: 딸깍은 'AI로 한 번에 처리'를 표제 뜻으로 두고 원 밈(한쪽만 날로 먹는 대비)은
-- 유래로 내렸다. 무지성·국뽕·알빠노는 무례하지만 욕설·19금이 아니라 category를 new-slang으로 뒀다.
-- 라떼는 말이야는 사전이 아니라 홈의 '오늘의 실전 표현'(dailyPicks.ts)으로 보냈다.
--
-- id는 410부터 — 386~409는 20260908090000_add_thirtytwo_love_words.sql 이 선점한 번호이며,
-- 그중 386 이후는 아직 운영 DB에 적용되지 않았다(별도 확인 필요).
--
-- NOTE: filename timestamp differs from the production migration version
-- (MCP apply time becomes the version) — repo-wide convention, see CLAUDE.md.

begin;

insert into public.words (id, word, category, short_desc, pronunciation, short_desc_i18n, origin, origin_i18n, usage, usage_i18n, romanization, meanings, related_words, aliases, likes, saves, translations) values
('410', '답정너', 'new-slang', '원하는 답을 정해놓고 묻는 사람', '[답쩡너]',
 '{"de": "Wer fragt, obwohl die Antwort feststeht", "en": "Someone who asks with the answer already decided", "es": "Quien pregunta con la respuesta ya decidida", "ja": "聞きたい答えを決めて質問する人", "vi": "Người hỏi mà đã định sẵn câu trả lời"}'::jsonb,
 '「답은 정해져 있고 너는 대답만 하면 돼」를 줄인 말이라는 데는 이견이 없으나 발생 시점은 확정되지 않았다. 2014년경 온라인 커뮤니티 유머 게시물 제목에서 나왔다는 설과, 2013년 tvN 《롤러코스터》가 소개하며 퍼졌다는 설이 함께 전해진다. 2010년대 중반 온라인에서 폭발적으로 확산됐다.',
 '{"de": "Unstrittig ist die Kurzform von „die Antwort steht fest, du sagst sie nur“; der Beginn ist unklar: eine Version nennt einen Community-Thread-Titel um 2014, eine andere die tvN-Sendung Roller Coaster von 2013. Mitte der 2010er verbreitete es sich explosionsartig im Netz.", "en": "Everyone agrees it shortens “the answer is decided and you just say it,” but the start date is unsettled: one account traces it to a community humor thread title around 2014, another to the tvN show Roller Coaster introducing it in 2013. It exploded online in the mid-2010s.", "es": "Nadie discute que abrevia “la respuesta está decidida y tú solo la dices”, pero la fecha no está clara: una versión la sitúa en el título de un hilo de humor hacia 2014, otra en el programa de tvN Roller Coaster de 2013. Estalló en internet a mediados de los 2010.", "ja": "「答えは決まっていて君は言うだけ」の略という点に異論はないが発生時期は未確定。2014年ごろのコミュニティのユーモア投稿タイトル説と、2013年にtvN『ローラーコースター』が紹介して広まった説がある。2010年代半ばにネットで爆発的に拡散した。", "vi": "Không ai tranh cãi rằng nó rút gọn từ “đáp án đã định, bạn chỉ việc nói”, nhưng thời điểm xuất hiện chưa rõ: một thuyết cho là tiêu đề bài hài trên cộng đồng khoảng 2014, thuyết khác cho là chương trình Roller Coaster của tvN năm 2013. Nó bùng nổ trên mạng giữa thập niên 2010."}'::jsonb,
 '가볍게 놀리는 말이지만 면전에 대고 쓰면 무례하게 들린다. 상대의 질문이 사실은 칭찬이나 동의를 요구하는 것일 때 뒤에서 하는 말로 더 자주 쓴다.',
 '{"de": "Eine leichte Neckerei, ins Gesicht gesagt aber unhöflich. Häufiger hinter dem Rücken über Fragen, die eigentlich Lob oder Zustimmung einfordern.", "en": "A light tease, but rude said to someone''s face. More often used behind their back about a question that is really a demand for praise or agreement.", "es": "Es una burla ligera, pero de frente suena grosero. Se usa más a espaldas de quien en realidad busca halagos o que le den la razón.", "ja": "軽いからかいだが、面と向かって言うと失礼。実は褒めや同意を求めている質問について、陰で言うことのほうが多い。", "vi": "Là lời trêu nhẹ, nhưng nói thẳng mặt thì thô lỗ. Thường dùng sau lưng, khi câu hỏi thực chất là đòi lời khen hay sự đồng tình."}'::jsonb,
 'Dap-Jeong-Neo',
 '[{"type": "줄임말", "examples": [{"de": "Fragt „bin ich dicker geworden?“ — die Antwort steht längst fest.", "es": "Pregunta “¿he engordado?”… la respuesta ya la tiene decidida.", "ja": "「私太った?」って聞いてくるけど、完全に答え決まってるやつ。", "vi": "Hỏi “tớ béo lên hả?” — kiểu đã định sẵn câu trả lời rồi.", "eng": "She asks “have I gained weight?” — total fishing-for-compliments question.", "kor": "「나 살쪘지?」 하고 물어보는데 완전 답정너야."}, {"de": "Wenn die Antwort eh feststeht, frag gar nicht erst.", "es": "Si ya tienes la respuesta, no preguntes.", "ja": "どうせ答え決まってるなら聞かないで。", "vi": "Đã định sẵn đáp án rồi thì đừng hỏi nữa.", "eng": "If the answer''s already decided, don''t bother asking.", "kor": "어차피 답정너면 그냥 물어보지 마."}], "definition": "「답은 정해져 있고 너는 대답만 하면 돼」의 줄임말. 듣고 싶은 대답을 이미 정해두고 형식적으로 질문하는 사람, 또는 그런 질문 자체를 가리킨다. 한쪽 성별을 콕 집을 때는 「답정남」·「답정녀」로도 쓴다.", "definition_i18n": {"de": "Kurz für „die Antwort steht fest, du musst sie nur sagen“. Bezeichnet jemanden, der mit vorgefertigter Wunschantwort fragt — oder die Frage selbst. Es gibt die Varianten 답정남 / 답정녀.", "en": "Short for “the answer is already decided and you just have to say it.” Refers to a person who asks a question with the desired reply pre-scripted — or to the question itself. Gendered variants 답정남 / 답정녀 also exist.", "es": "Abreviatura de “la respuesta ya está decidida y tú solo tienes que decirla”. Alguien que pregunta con la respuesta deseada ya fijada, o la pregunta misma. Existen las variantes 답정남 / 답정녀.", "ja": "「答えは決まっていて君は言うだけ」の略。聞きたい返事をあらかじめ決めて形だけ質問する人、またはその質問自体。性別を指すときは「タプジョンナム/タプジョンニョ」とも。", "vi": "Viết tắt của “câu trả lời đã định sẵn, bạn chỉ việc nói ra”. Chỉ người đặt câu hỏi mà đã có sẵn đáp án mong muốn, hoặc chính câu hỏi đó. Có biến thể theo giới 답정남 / 답정녀."}}]'::jsonb,
 array['팩폭','안물안궁','취존'], array['답정남','답정녀'], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Fishing for a set answer"}, {"lang": "🇯🇵 JA", "text": "答えありきの質問"}, {"lang": "🇨🇳 ZH", "text": "答案早就定好的提问"}, {"lang": "🇻🇳 VI", "text": "Hỏi mà đã có sẵn đáp án"}, {"lang": "🇪🇸 ES", "text": "Pregunta con respuesta ya decidida"}, {"lang": "🇩🇪 DE", "text": "Frage mit feststehender Antwort"}]'::jsonb),
('411', '소확행', 'new-slang', '작지만 확실하게 손에 잡히는 행복', '[소화캥]',
 '{"de": "Kleines, aber sicheres Glück", "en": "Small but certain everyday happiness", "es": "Felicidad pequeña pero segura", "ja": "小さくても確実な幸せ", "vi": "Hạnh phúc nhỏ mà chắc chắn"}'::jsonb,
 '일본 작가 무라카미 하루키가 1986년 에세이집 《랑게르한스섬의 오후》에서 만들어 쓴 조어 「小確幸」에서 왔다. 레이먼드 카버의 단편 〈A Small, Good Thing〉에서 착안했다고 알려져 있으며, 일본어 사전에는 오르지 않은 하루키의 개인 조어다. 한국에서는 2018년 트렌드 키워드로 소개되면서 일상어로 자리 잡았다.',
 '{"de": "Geprägt vom japanischen Autor Haruki Murakami in seinem Essayband von 1986, Nachmittag auf den Langerhans-Inseln — angeblich inspiriert von Raymond Carvers Erzählung „A Small, Good Thing“. Es ist Murakamis eigene Wortschöpfung, kein japanisches Wörterbuchwort. In Korea wurde es 2018 als Trendbegriff popularisiert und alltäglich.", "en": "Coined by Japanese novelist Haruki Murakami in his 1986 essay collection Afternoon in the Islets of Langerhans, reportedly inspired by Raymond Carver''s story “A Small, Good Thing.” It is Murakami''s own coinage, not a Japanese dictionary word. In Korea it took hold as everyday vocabulary after being pushed as a 2018 trend keyword.", "es": "Acuñado por el novelista japonés Haruki Murakami en su libro de ensayos de 1986 Tarde en las islas de Langerhans, inspirado según se dice en el relato de Raymond Carver “A Small, Good Thing”. Es una invención suya, no está en los diccionarios japoneses. En Corea se asentó como palabra cotidiana tras ser lanzada como palabra de tendencia en 2018.", "ja": "日本の作家・村上春樹が1986年のエッセイ集『ランゲルハンス島の午後』で作った造語「小確幸」に由来。レイモンド・カーヴァーの短編「ささやかだけれど、役にたつこと」から着想したとされ、日本語辞書にはない春樹の個人的造語。韓国では2018年のトレンドキーワードとして紹介され日常語になった。", "vi": "Do nhà văn Nhật Haruki Murakami đặt ra trong tập tùy bút năm 1986 Buổi chiều ở đảo Langerhans, được cho là lấy cảm hứng từ truyện ngắn “A Small, Good Thing” của Raymond Carver. Đây là từ tự chế của ông, không có trong từ điển Nhật. Ở Hàn Quốc nó thành từ thường ngày sau khi được giới thiệu như từ khóa xu hướng 2018."}'::jsonb,
 '긍정적인 말이라 부담 없이 쓴다. 자기 취향이나 소비를 설명할 때 흔히 붙이며, 큰 목표를 포기했다는 뜻은 아니다.',
 '{"de": "Ein positives Wort, das man unbefangen nutzt — oft beim Erklären eigener Vorlieben oder Ausgaben. Es heißt nicht, dass man große Ziele aufgegeben hat.", "en": "A positive word you can use freely — often attached when explaining your own tastes or spending. It does not imply you''ve given up on bigger goals.", "es": "Palabra positiva y de uso libre; suele acompañar la explicación de gustos o gastos propios. No implica haber renunciado a metas grandes.", "ja": "肯定的な言葉で気軽に使える。自分の好みや消費を説明するときによく添える。大きな目標を諦めたという意味ではない。", "vi": "Từ tích cực, dùng thoải mái; hay gắn khi nói về sở thích hay chi tiêu của mình. Không hàm ý từ bỏ mục tiêu lớn."}'::jsonb,
 'So-Hwak-Haeng',
 '[{"type": "줄임말", "examples": [{"de": "Nach der Arbeit ein Bier vom Kiosk — das ist mein kleines, sicheres Glück.", "es": "Una cerveza del súper 24 h al salir del trabajo: esa es mi felicidad pequeña y segura.", "ja": "仕事帰りのコンビニのビール一缶、これが私の小確幸。", "vi": "Một lon bia tiện lợi sau giờ làm, đó là hạnh phúc nhỏ của mình.", "eng": "A convenience-store beer after work — that''s my small-but-certain happiness.", "kor": "퇴근하고 편의점 맥주 한 캔, 이게 내 소확행이야."}, {"de": "Am Wochenende ausschlafen ist derzeit meine einzige kleine Freude.", "es": "Dormir hasta tarde el finde es mi única alegría estos días.", "ja": "週末の寝坊が最近唯一の小確幸。", "vi": "Ngủ nướng cuối tuần là niềm vui nhỏ duy nhất của mình dạo này.", "eng": "Sleeping in on weekends is my only little joy these days.", "kor": "주말에 늦잠 자는 게 요즘 유일한 소확행이야."}], "definition": "「소소하지만 확실한 행복」의 줄임말. 언제 올지 모를 큰 성공 대신, 지금 당장 확실히 누릴 수 있는 작은 즐거움을 챙기는 태도나 그런 순간을 가리킨다.", "definition_i18n": {"de": "Kurz für „kleines, aber sicheres Glück“. Die Haltung, die kleinen Freuden von jetzt zu nehmen statt auf großen, ungewissen Erfolg zu warten — oder diese Momente selbst.", "en": "Short for “small but certain happiness.” The attitude of taking the small joys you can actually have right now instead of waiting on some big, uncertain success — or the moments themselves.", "es": "Abreviatura de “felicidad pequeña pero segura”. La actitud de disfrutar las alegrías pequeñas de ahora en vez de esperar un gran éxito incierto, o esos mismos momentos.", "ja": "「ささやかだけど確実な幸せ」の略。いつ来るか分からない大きな成功より、今すぐ確実に味わえる小さな喜びを大事にする態度、またはその瞬間。", "vi": "Viết tắt của “hạnh phúc nhỏ mà chắc chắn”. Thái độ tận hưởng niềm vui nhỏ có ngay bây giờ thay vì chờ thành công lớn xa vời, hoặc chính những khoảnh khắc ấy."}}]'::jsonb,
 array['워라밸','갓생','혼밥'], array['소소하지만 확실한 행복'], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Small but certain happiness"}, {"lang": "🇯🇵 JA", "text": "小確幸(ささやかで確実な幸せ)"}, {"lang": "🇨🇳 ZH", "text": "小确幸"}, {"lang": "🇻🇳 VI", "text": "Hạnh phúc nhỏ mà chắc chắn"}, {"lang": "🇪🇸 ES", "text": "Felicidad pequeña pero segura"}, {"lang": "🇩🇪 DE", "text": "Kleines, sicheres Glück"}]'::jsonb),
('412', '쉬었음 청년', 'new-slang', '구직도 취업 준비도 안 하고 그냥 쉬는 청년', '[쉬어씀 청년]',
 '{"en": "Young adults who are neither working nor job-hunting", "ja": "就職も求職もせずただ休んでいる若者", "es": "Jóvenes que ni trabajan ni buscan trabajo", "vi": "Người trẻ không đi làm cũng không tìm việc", "de": "Junge Menschen, die weder arbeiten noch Arbeit suchen"}'::jsonb,
 '통계청 경제활동인구조사의 비경제활동인구 활동 상태 항목 「쉬었음」에서 왔다. 일할 능력은 있으나 육아·학업·질병 같은 뚜렷한 이유 없이 「그냥 쉬었다」고 답한 사람을 가리키는 조사 용어인데, 2024~2025년 청년층 「쉬었음」 인구가 크게 늘며 언론이 「쉬었음 청년」으로 묶어 쓰기 시작해 일상어로 굳었다.',
 '{"en": "From the 쉬었음 (\"resting\") category in Statistics Korea''s labour force survey — able to work but not doing so for no clear reason such as childcare, study or illness. As the youth figure climbed sharply in 2024-2025, the press coined 쉬었음 청년 and it entered everyday speech.", "ja": "統計庁の経済活動人口調査で非経済活動人口の活動状態を示す「쉬었음(休んだ)」から。働く能力はあるが、育児・学業・病気といった明確な理由なく「ただ休んでいる」と答えた人を指す調査用語。2024〜25年に若年層のこの数字が急増し、メディアが「쉬었음 청년」とまとめて呼び始めて日常語になった。", "es": "Viene de la categoría 쉬었음 (\"descansando\") de la encuesta de población activa de Corea: personas capaces de trabajar que no lo hacen sin motivo claro como cuidados, estudios o enfermedad. Al dispararse la cifra juvenil en 2024-2025, la prensa acuñó 쉬었음 청년.", "vi": "Từ mục 쉬었음 (\"nghỉ ngơi\") trong khảo sát lực lượng lao động của Tổng cục Thống kê Hàn Quốc — có khả năng làm việc nhưng không làm, mà không vì lý do rõ ràng như chăm con, đi học hay bệnh tật. Khi con số ở nhóm trẻ tăng mạnh 2024-2025, báo chí gọi gộp là 쉬었음 청년 và từ này thành lời nói thường ngày.", "de": "Aus der Kategorie „쉬었음“ (ausgeruht) der amtlichen Arbeitskräfteerhebung: arbeitsfähig, aber ohne klaren Grund wie Kinderbetreuung, Studium oder Krankheit einfach nicht erwerbstätig. Als die Zahl junger Menschen in dieser Kategorie 2024–2025 stark stieg, prägten die Medien den Begriff 쉬었음 청년."}'::jsonb,
 '뉴스나 시사 대화에서 사회 현상을 가리킬 때 쓴다. 구직 활동을 한 「실업자」와 통계상 구분되는 말이다. 당사자를 앞에 두고 부르면 낙인처럼 들릴 수 있어, 사람을 가리키기보다 현상을 이야기할 때 쓰는 편이 낫다.',
 '{"en": "Used in news and current-affairs talk about the phenomenon; statistically distinct from the \"unemployed\", who are actively job-hunting. Said to someone''s face it sounds like a label, so it is better aimed at the trend than at a person.", "ja": "ニュースや時事の話題で社会現象を指すときに使う。求職活動をした「失業者」とは統計上区別される。本人に向けて言うとレッテルに聞こえるので、人ではなく現象を指して使うほうがよい。", "es": "Se usa en noticias y conversaciones sobre el fenómeno; estadísticamente distinto de los \"parados\", que sí buscan empleo. Dicho a la cara suena a etiqueta, así que es mejor referirse al fenómeno que a una persona.", "vi": "Dùng khi nói về hiện tượng xã hội trên báo chí hay chuyện thời sự; khác với \"người thất nghiệp\" (có tìm việc) về mặt thống kê. Nói thẳng vào mặt ai đó nghe như dán nhãn, nên dùng để chỉ hiện tượng thì hơn.", "de": "Wird in Nachrichten und Gesprächen über gesellschaftliche Themen verwendet; statistisch getrennt von „Arbeitslosen“, die aktiv suchen. Direkt an eine Person gerichtet klingt es stigmatisierend — besser über das Phänomen als über Menschen sprechen."}'::jsonb,
 'Swieoteum Cheongnyeon',
 '[{"type": "명사", "definition": "일할 능력이 있는데도 구직도 취업 준비도 하지 않고 그냥 쉬고 있는 청년. 통계청이 쓰는 「쉬었음」 분류에서 나온 말로, 적극적으로 일자리를 찾은 「실업자」와는 구분된다.", "definition_i18n": {"en": "A young adult who could work but is neither job-hunting nor preparing for a job — from Statistics Korea''s 쉬었음 category, and distinct from the \"unemployed\", who are actively looking.", "ja": "働く能力はあるのに求職も就職準備もせずただ休んでいる若者。統計庁の「쉬었음」区分から来た語で、積極的に職を探した「失業者」とは区別される。", "es": "Joven que podría trabajar pero ni busca empleo ni se prepara para ello — de la categoría oficial 쉬었음, distinta de los \"parados\", que sí buscan.", "vi": "Người trẻ có khả năng làm việc nhưng không tìm việc cũng không chuẩn bị đi làm — từ mục 쉬었음 của Tổng cục Thống kê, khác với \"người thất nghiệp\" đang tích cực tìm việc.", "de": "Junge Erwachsene, die arbeiten könnten, aber weder arbeiten noch sich bewerben. Aus der amtlichen Kategorie „쉬었음“; abzugrenzen von „Arbeitslosen“, die aktiv suchen."}, "examples": [{"kor": "요즘 쉬었음 청년이 50만 명 가까이 된대.", "eng": "They say there are nearly 500,000 young people in the \"resting\" category now.", "ja": "最近「쉬었음 청년」が50万人近いんだって。", "es": "Dicen que ya hay casi 500.000 jóvenes en la categoría de \"descanso\".", "vi": "Nghe nói giờ có gần 500.000 người trẻ thuộc diện \"nghỉ ngơi\".", "de": "Es soll fast 500.000 junge Menschen in der Kategorie „ausgeruht“ geben."}]}]'::jsonb,
 array['퇴준생','갓생'], array['쉬었음'], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Youth \"at rest\" — neither working nor job-hunting"}, {"lang": "🇯🇵 JA", "text": "就職も求職もせず休んでいる若者"}, {"lang": "🇨🇳 ZH", "text": "既不工作也不找工作的青年"}, {"lang": "🇻🇳 VI", "text": "Người trẻ không làm cũng không tìm việc"}, {"lang": "🇪🇸 ES", "text": "Jóvenes que ni trabajan ni buscan empleo"}, {"lang": "🇩🇪 DE", "text": "Junge Menschen ohne Job und ohne Jobsuche"}]'::jsonb),
('413', '딸깍', 'new-slang', '클릭 한 번으로 손쉽게 해치우는 것', NULL,
 '{"de": "Mit einem einzigen Klick erledigt", "en": "Getting it done with a single click", "es": "Resolverlo con un solo clic", "ja": "クリック一回で軽く片づけること", "vi": "Xong việc chỉ bằng một cú nhấp"}'::jsonb,
 '원전은 일러스트레이터 PjkKA가 2015년 하스스톤 커뮤니티에 올린 만화로 알려져 있다. 한쪽은 죽어라 고생하는데 다른 쪽은 「딸깍」 한 번으로 끝내는 대비가 밈이 됐고, 생성형 AI가 대중화된 2024년 이후 「AI 딸깍」이라는 쓰임으로 크게 번졌다. 노력 없이 결과만 챙긴다고 비난할 때 쓰는 파생어 「딸깍충」도 여기서 나왔다.',
 '{"de": "Als Ursprung gilt ein Comic, den Illustrator PjkKA 2015 in einer Hearthstone-Community postete: die eine Seite schuftet, die andere klickt einmal. Nach dem KI-Boom 2024 explodierte die Wendung „AI 딸깍“. Der abwertende Ableger 딸깍충 stammt ebenfalls daher.", "en": "The source is said to be a 2015 webcomic posted to a Hearthstone community by illustrator PjkKA: one side grinds, the other finishes with a single click. After generative AI went mainstream in 2024 the phrase exploded as “AI 딸깍”. The derogatory spin-off 딸깍충 (someone who claims credit for one-click AI output) comes from the same root.", "es": "Se atribuye a un cómic que el ilustrador PjkKA subió en 2015 a una comunidad de Hearthstone: uno se parte el lomo y el otro termina con un clic. Tras la popularización de la IA generativa en 2024 estalló como “AI 딸깍”. De ahí sale el despectivo 딸깍충.", "ja": "原典はイラストレーターPjkKAが2015年にハースストーンのコミュニティへ投稿した漫画とされる。片方は必死で苦労し、もう片方は「カチッ」一回で終える対比がミーム化。2024年以降の生成AI普及で「AIカチッ」の用法が急拡大した。努力せず成果だけ得る人を非難する派生語「カチッ虫(딸깍충)」も同じ流れ。", "vi": "Nguồn gốc được cho là truyện tranh do họa sĩ PjkKA đăng lên cộng đồng Hearthstone năm 2015: một bên cày cuốc, bên kia nhấp một cái là xong. Sau khi AI tạo sinh phổ biến năm 2024, cụm “AI 딸깍” bùng nổ. Từ phái sinh mỉa mai 딸깍충 cũng từ đây."}'::jsonb,
 '부러움 반 비아냥 반. 자기 일을 두고 「딸깍했다」고 하면 겸손하거나 자조하는 말이 되지만, 남에게 쓰면 「노력 안 했다」는 폄하로 들릴 수 있다.',
 '{"de": "Halb Neid, halb Spitze. Über die eigene Arbeit klingt es bescheiden oder selbstironisch; über andere schnell wie „du hast nichts geleistet“.", "en": "Half envy, half jab. Said about your own work it sounds modest or self-mocking; said about someone else it can read as “you didn''t actually work for it.”", "es": "Mitad envidia, mitad pulla. Sobre lo propio suena modesto o autoirónico; sobre otro puede sonar a “no te lo curraste”.", "ja": "半分うらやみ、半分皮肉。自分の仕事に使えば謙遜や自嘲になるが、他人に使うと「努力していない」という見下しに聞こえる。", "vi": "Nửa ghen tị, nửa mỉa. Nói về việc của mình thì nghe khiêm tốn hay tự giễu; nói về người khác dễ thành chê “chẳng nỗ lực gì”."}'::jsonb,
 'Ttal-Kkak',
 '[{"type": "명사·부사", "examples": [{"de": "Der Bericht? Einmal Klick mit KI, fertig.", "es": "¿El informe? Un clic con la IA y listo.", "ja": "レポート? AIでカチッと出した。", "vi": "Báo cáo hả? Nhấp phát bằng AI là xong.", "eng": "The report? One click with AI, done.", "kor": "보고서? AI로 딸깍 했지."}, {"de": "Ich hab die ganze Nacht gezeichnet und die klicken einmal …", "es": "Yo dibujé toda la noche y esa persona hizo un clic…", "ja": "こっちは徹夜で描いたのに、あっちはカチッ一回か…", "vi": "Mình vẽ cả đêm còn người ta nhấp một cái…", "eng": "I drew all night and they just clicked once…", "kor": "나는 밤새 그렸는데 쟨 딸깍 한 번이네…"}], "definition": "마우스 클릭 소리 「딸깍」에서 온 말. 남들은 고생해서 하는 일을 클릭 한 번으로 간단히 끝내는 상황을 가리킨다. 생성형 AI가 퍼진 뒤로는 「AI에 한 번 시켜서 뚝딱 뽑았다」는 뜻으로 쓰는 경우가 가장 흔하다.", "definition_i18n": {"de": "Vom Mausklick-Geräusch. Beschreibt, etwas mit einem Klick zu erledigen, wofür andere schuften; seit generativer KI meist: „hab’s die KI machen lassen“.", "en": "From the click of a mouse. Describes finishing in one click what others grind through; since generative AI spread, it most often means “I just had the AI do it.”", "es": "Del sonido del clic del ratón. Describe acabar de un clic lo que a otros les cuesta; desde la IA generativa suele significar “se lo pedí a la IA y ya”.", "ja": "マウスのクリック音「カチッ」から。他人が苦労することをワンクリックで終える状況を指す。生成AIの普及後は「AIにやらせて一発で出した」の意味が最も一般的。", "vi": "Từ tiếng nhấp chuột. Chỉ việc xong trong một cú nhấp thứ người khác phải vất vả; từ khi AI tạo sinh phổ biến, nó thường nghĩa là “nhờ AI làm phát xong”."}}]'::jsonb,
 array['개이득','핵이득','갓생'], array['딸깍딸깍'], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "One-click / just let the AI do it"}, {"lang": "🇯🇵 JA", "text": "ワンクリックで(AI任せ)"}, {"lang": "🇨🇳 ZH", "text": "一键搞定(交给AI)"}, {"lang": "🇻🇳 VI", "text": "Một cú nhấp là xong"}, {"lang": "🇪🇸 ES", "text": "De un clic (se lo pedí a la IA)"}, {"lang": "🇩🇪 DE", "text": "Ein Klick, fertig (KI macht’s)"}]'::jsonb),
('414', '누칼협', 'new-slang', '네가 선택한 일이니 네 책임이라는 비꼼', NULL,
 '{"de": "Du hast es gewählt — niemand hat dich gezwungen", "en": "You chose it — nobody forced you, so own it", "es": "Tú lo elegiste, nadie te obligó — asúmelo", "ja": "自分で選んだんだから自己責任、という皮肉", "vi": "Tự bạn chọn, không ai ép — tự chịu đi"}'::jsonb,
 '「누가 칼 들고 협박함?」의 줄임말. 게임 로스트아크 커뮤니티에서 시작됐다는 설명이 가장 널리 인용되지만 확정된 것은 아니다. 2022년 인터넷 전반으로 번졌고, 그해 말 언론이 「중꺾마」와 대비되는 그해의 정서로 함께 다뤘다.',
 '{"de": "Kurz für „wer hat dich mit dem Messer bedroht?“. Am häufigsten wird die Lost-Ark-Spielercommunity als Ursprung genannt, bestätigt ist das nicht. 2022 verbreitete es sich im Netz; zum Jahresende stellte die Presse es 중꺾마 gegenüber.", "en": "Short for “who held a knife and forced you?” The most-cited account traces it to the Lost Ark game community, but that is not confirmed. It spread across the Korean internet in 2022, and at year''s end the press paired it with 중꺾마 as the two moods of the year.", "es": "Abreviatura de “¿quién te amenazó con un cuchillo?”. La versión más citada la sitúa en la comunidad del juego Lost Ark, pero no está confirmada. Se extendió por internet en 2022 y a fin de año la prensa la contrapuso a 중꺾마.", "ja": "「誰がナイフを突きつけて脅した?」の略。ゲーム「ロストアーク」のコミュニティ発という説明が最も広く引用されるが未確定。2022年にネット全体へ広がり、年末には報道で「チュンコンマ」と対比される年の空気として扱われた。", "vi": "Viết tắt của “ai kề dao ép bạn?”. Cách giải thích được dẫn nhiều nhất cho rằng nó khởi từ cộng đồng game Lost Ark, nhưng chưa được xác nhận. Nó lan khắp mạng năm 2022, cuối năm báo chí đặt cạnh 중꺾마 như hai tâm thế của năm."}'::jsonb,
 '냉정한 자기책임론으로 읽히기도 하지만 대개는 공감을 거부하는 조롱이라 상대에게 상처를 준다. 남에게 쓰기보다 자기 상황을 자조할 때 쓰는 편이 무난하다.',
 '{"de": "Klingt manchmal nach harter Eigenverantwortung, ist meist aber ein empathieloser Seitenhieb, der verletzt. Sicherer auf die eigene Lage gemünzt.", "en": "It can read as tough-love personal responsibility, but usually it''s a jab that refuses empathy and stings. Safer aimed at your own situation than at someone else.", "es": "Puede sonar a responsabilidad personal dura, pero suele ser una pulla que niega la empatía y duele. Más seguro usarlo sobre uno mismo.", "ja": "厳しい自己責任論に聞こえることもあるが、たいていは共感を拒む嘲りで相手を傷つける。他人にではなく自分の状況に使うほうが無難。", "vi": "Có thể nghe như bài học tự chịu trách nhiệm, nhưng thường là lời châm chọc từ chối đồng cảm và gây tổn thương. An toàn hơn khi tự nói về mình."}'::jsonb,
 'Nu-Kal-Hyeop',
 '[{"type": "줄임말", "examples": [{"de": "Überstunden nerven? Gezwungen hat dich keiner.", "es": "¿Que las horas extra te matan? Nadie te obligó.", "ja": "残業きついって? 誰も強制してないよね。", "vi": "Tăng ca mệt hả? Có ai ép đâu.", "eng": "Overtime''s killing you? Nobody held a knife to your throat.", "kor": "야근 힘들다며? 누칼협."}, {"de": "Die Aktie hab ich selbst gekauft — wem soll ich die Schuld geben?", "es": "Compré las acciones yo mismo, no hay a quién culpar.", "ja": "自分で買った株だし、誰のせいにもできないよね。", "vi": "Cổ phiếu tự tôi mua, trách ai được, tự chịu thôi.", "eng": "I bought the stock myself — nobody to blame but me.", "kor": "내가 산 주식인데 누구 탓하겠어, 누칼협이지."}], "definition": "「누가 칼 들고 협박했냐」의 줄임말. 스스로 선택한 일의 결과를 두고 힘들다고 하소연하는 사람에게 「강요한 사람 없으니 책임도 네 몫」이라고 비꼬는 말.", "definition_i18n": {"de": "Kurz für „wer hat dir ein Messer angesetzt?“ — an jemanden gerichtet, der über eine selbst gewählte Lage klagt: dich hat niemand gezwungen.", "en": "Short for “who held a knife to you and forced it?” Thrown at someone complaining about a situation they chose, meaning: nobody made you, so it''s on you.", "es": "Abreviatura de “¿quién te puso un cuchillo encima?”. Se lanza a quien se queja de algo que eligió: nadie te obligó, así que es cosa tuya.", "ja": "「誰がナイフを突きつけて脅した?」の略。自分で選んだことを愚痴る人に「誰も強制していないから自己責任」と皮肉る言葉。", "vi": "Viết tắt của “ai kề dao ép bạn?”. Ném vào người than vãn về điều chính họ chọn: không ai ép, nên tự chịu."}}]'::jsonb,
 array['알빠노','중꺾마','팩폭'], array['누가 칼 들고 협박했냐'], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Nobody forced you / your own fault"}, {"lang": "🇯🇵 JA", "text": "誰も強制してない(自己責任)"}, {"lang": "🇨🇳 ZH", "text": "没人逼你,自己负责"}, {"lang": "🇻🇳 VI", "text": "Không ai ép, tự chịu"}, {"lang": "🇪🇸 ES", "text": "Nadie te obligó"}, {"lang": "🇩🇪 DE", "text": "Gezwungen hat dich keiner"}]'::jsonb),
('415', '알빠노', 'new-slang', '내 알 바 아니라는 뜻의 무심한 대꾸', NULL,
 '{"de": "Nicht mein Problem — eine schroffe Abfuhr", "en": "Not my problem — a blunt brush-off", "es": "No es mi problema — una respuesta cortante", "ja": "「知ったことか」という冷たい返し", "vi": "Không phải việc của tôi — câu đáp lạnh lùng"}'::jsonb,
 '「(내) 알 바 아니다」에 인터넷 말투 어미 「-노」가 붙은 형태. 2022년 트위치 스트리머 PAKA의 리그 오브 레전드 방송에서 나온 대답이 밈으로 굳은 계기라는 설명이 널리 인용되지만, 그 이전부터 쓰이던 표현이라는 말도 있어 최초 시점은 확정되지 않았다. 2023년 「누칼협」과 함께 언론에 다뤄지며 대중화됐다.',
 '{"de": "Von „geht mich nichts an“ plus der Netz-Endung -no. Häufig wird ein Twitch-Stream von PAKA 2022 als Meme-Auslöser genannt, doch der Ausdruck kursierte schon früher — die Herkunft ist ungeklärt. 2023 wurde er durch Presseberichte neben 누칼협 breit bekannt.", "en": "From “not my business” plus the internet-slang ending -no. A widely cited account credits a 2022 Twitch stream by PAKA for cementing it as a meme, but the phrase circulated earlier, so the true origin is unsettled. It went mainstream in 2023 when the press covered it alongside 누칼협.", "es": "De “no es asunto mío” más la terminación de internet -no. Se cita mucho una transmisión de Twitch de PAKA en 2022 como el momento en que se volvió meme, pero la expresión ya circulaba antes, así que el origen no está confirmado. Se popularizó en 2023 con la cobertura de prensa junto a 누칼협.", "ja": "「知ったことか」にネット語尾「ノ」が付いた形。2022年のTwitch配信者PAKAの発言でミーム化したという説明が広く引用されるが、それ以前から使われていたとも言われ起源は未確定。2023年に「ヌカルヒョプ」とともに報道され広まった。", "vi": "Từ “không phải việc của tôi” cộng đuôi mạng -no. Nhiều nguồn dẫn buổi stream Twitch của PAKA năm 2022 là lúc nó thành meme, nhưng cụm này đã có từ trước nên nguồn gốc chưa chắc chắn. Nó phổ biến năm 2023 khi báo chí đưa tin cùng 누칼협."}'::jsonb,
 '상대의 고민이나 부탁을 냉정하게 자르는 말이라 진지하게 던지면 크게 무례하게 들린다. 친한 사이의 농담이나 자기 자신에 대한 자조로 쓰는 것이 안전하다.',
 '{"de": "Es blockt die Sorgen anderer eiskalt ab und wirkt ernst gemeint sehr unhöflich. Sicher nur als Scherz unter engen Freunden oder als Selbstironie.", "en": "It shuts down someone''s worry cold, so said seriously it lands as very rude. Safest as a joke among close friends or as self-deprecation.", "es": "Corta en seco la preocupación del otro, así que en serio suena muy grosero. Mejor como broma entre amigos cercanos o autoburla.", "ja": "相手の悩みを冷たく切る言葉なので、本気で言うとかなり失礼。親しい間柄の冗談か自嘲で使うのが無難。", "vi": "Nó cắt phăng nỗi lo của người khác nên nói nghiêm túc sẽ rất thô lỗ. An toàn nhất là đùa với bạn thân hoặc tự giễu."}'::jsonb,
 'Al-Ppa-No',
 '[{"type": "줄임말", "examples": [{"de": "Ich hab die Prüfung verhauen … / Und das interessiert mich warum?", "es": "Suspendí el examen… / ¿Y a mí qué?", "ja": "試験ダメだった… / 知らんがな?", "vi": "Tớ thi tạch rồi… / Liên quan gì tớ?", "eng": "I bombed the exam… / And that''s my problem how?", "kor": "나 시험 망했어… / 알빠노?"}, {"de": "Morgen soll es regnen. / Ich hab einen Schirm — nicht mein Problem~", "es": "Dicen que mañana llueve. / Yo tengo paraguas, así que… ni fu ni fa.", "ja": "明日雨だって。 / 俺傘あるし、知らんがな〜", "vi": "Mai mưa đấy. / Tớ có ô rồi, kệ thôi~", "eng": "It''s supposed to rain tomorrow. / I''ve got an umbrella, so… not my problem.", "kor": "내일 비 온대. / 나 우산 있는데? 알빠노~"}], "definition": "「내가 알 바 아니다」를 줄여 만든 말. 남의 사정이나 하소연에 관심 없다고 딱 잘라 말할 때 쓴다. 끝의 「-노」는 인터넷에서 흔한 경상도 방언투 어미다.", "definition_i18n": {"de": "Kurz für „geht mich nichts an“. Eine schroffe Absage an fremde Sorgen; die Endung -no imitiert den im Netz beliebten Gyeongsang-Dialekt.", "en": "Short for “that''s not my business.” A flat refusal to care about someone''s troubles; the -no ending mimics a Gyeongsang-dialect internet speech style.", "es": "Abreviatura de “no es asunto mío”. Corta en seco el interés por los problemas ajenos; la terminación -no imita el dialecto de Gyeongsang usado en internet.", "ja": "「俺の知ったことか」の略。他人の事情や愚痴に関心がないと突き放すときに使う。語尾の「ノ」はネット上で定番の慶尚道方言風。", "vi": "Viết tắt của “không phải việc của tôi”. Câu chặn đứng sự cảm thông với rắc rối của người khác; đuôi -no bắt chước giọng phương ngữ Gyeongsang trên mạng."}}]'::jsonb,
 array['누칼협','어쩔티비','손절'], array[]::text[], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Not my problem / whatever"}, {"lang": "🇯🇵 JA", "text": "知ったことか / 知らんがな"}, {"lang": "🇨🇳 ZH", "text": "关我什么事"}, {"lang": "🇻🇳 VI", "text": "Không phải việc của tôi"}, {"lang": "🇪🇸 ES", "text": "¿Y a mí qué?"}, {"lang": "🇩🇪 DE", "text": "Nicht mein Problem"}]'::jsonb),
('416', '무지성', 'new-slang', '생각 없이 그냥 하는 것', NULL,
 '{"de": "Ohne nachzudenken einfach machen", "en": "Doing it without thinking at all", "es": "Hacerlo sin pensar nada", "ja": "何も考えずにやること", "vi": "Làm mà chẳng suy nghĩ gì"}'::jsonb,
 '일본 만화 《진격의 거인》에 나오는 「무지성 거인」(자아 없이 본능만으로 움직이는 거인)을 가리키던 말에서 왔다는 설명이 출처들 사이에 일치한다. 이후 인터넷 커뮤니티와 게임·스트리밍 방송을 거쳐 일상 표현으로 번졌다. 국어사전에는 오르지 않은 신조어다.',
 '{"de": "Die Quellen sind sich einig: Es stammt von den „verstandslosen Titanen“ aus dem japanischen Manga Attack on Titan, die rein instinktiv handeln. Über Online-Communities, Gaming und Streaming wurde es Alltagssprache. Im Wörterbuch steht es nicht.", "en": "Sources agree it comes from the “mindless titans” of the Japanese manga Attack on Titan — titans that move on pure instinct with no self. It then spread through online communities, gaming and streaming into everyday speech. It is not a dictionary word.", "es": "Las fuentes coinciden en que viene de los “titanes sin raciocinio” del manga japonés Ataque a los titanes, que se mueven solo por instinto. Luego pasó de las comunidades online y el streaming al habla cotidiana. No figura en los diccionarios.", "ja": "日本の漫画『進撃の巨人』に登場する「無知性巨人」(自我なく本能だけで動く巨人)の呼称に由来するという説明で各出典が一致する。その後、ネットコミュニティやゲーム・配信を経て日常語に広がった。国語辞典には載っていない新造語。", "vi": "Các nguồn thống nhất rằng nó đến từ “khổng lồ vô trí” trong manga Nhật Attack on Titan — loài chỉ hành động theo bản năng. Sau đó nó lan từ cộng đồng mạng, game và stream vào lời nói thường ngày. Từ này không có trong từ điển."}'::jsonb,
 '자기 행동에 붙이면 자조 섞인 농담이 되지만, 남에게 「무지성이다」라고 하면 지능을 깎아내리는 인신공격이 되니 조심해야 한다.',
 '{"de": "Auf sich selbst gemünzt Selbstironie; jemanden 무지성 zu nennen ist ein persönlicher Angriff auf dessen Intelligenz — Vorsicht.", "en": "Self-applied it''s a self-deprecating joke, but calling someone else 무지성 is a personal attack on their intelligence — use with care.", "es": "Sobre uno mismo es autoburla; llamar 무지성 a otro es un ataque personal a su inteligencia, así que cuidado.", "ja": "自分に使えば自嘲の冗談だが、他人に「無知性だ」と言うと知能を貶す人身攻撃になるので注意。", "vi": "Tự nói về mình thì là đùa tự giễu, nhưng gọi người khác là 무지성 là công kích trí tuệ họ — nên cẩn thận."}'::jsonb,
 'Mu-Ji-Seong',
 '[{"type": "합성어", "examples": [{"de": "War im Sale, also hab ich ohne nachzudenken gekauft.", "es": "Estaba de oferta y lo compré sin pensarlo nada.", "ja": "セールだって聞いて何も考えずにポチった。", "vi": "Nghe bảo sale nên mình mua luôn chẳng nghĩ gì.", "eng": "It was on sale so I just bought it without thinking.", "kor": "세일이라길래 무지성으로 질렀어."}, {"de": "Renn nicht kopflos rein — denk kurz nach.", "es": "No te lances sin pensar; párate a pensarlo.", "ja": "何も考えずに突っ込まないで、少しは考えてやって。", "vi": "Đừng lao vào kiểu không não, nghĩ chút đi.", "eng": "Don''t just charge in on autopilot — think it through.", "kor": "무지성으로 달려들지 말고 좀 생각하고 해."}], "definition": "「없을 무(無)」와 「지성(知性)」을 합친 말로, 생각 없이 본능적으로 움직이는 상태나 그런 사람을 가리킨다. 남을 두고 쓰면 「머리를 안 쓴다」는 비난이지만, 자기 행동에 붙이면 「깊게 고민 안 하고 그냥」이라는 가벼운 부사처럼 쓴다.", "definition_i18n": {"de": "„Kein“ + „Intellekt“. Instinktives Handeln ohne Nachdenken oder eine Person, die so handelt. Auf andere gemünzt eine Beleidigung; auf sich selbst ein lockeres Adverb: „ohne groß zu überlegen einfach gemacht“.", "en": "“No” + “intellect.” Acting on instinct with no thought, or a person who does. Aimed at others it''s an insult about not using their head; about yourself it works as a casual adverb meaning “without overthinking, I just did it.”", "es": "“Sin” + “intelecto”. Actuar por instinto sin pensar, o quien lo hace. Dirigido a otros es un insulto sobre no usar la cabeza; sobre uno mismo funciona como adverbio informal: “sin darle vueltas, lo hice y ya”.", "ja": "「無」と「知性」の合成語。何も考えず本能的に動く状態や、そういう人を指す。他人に使えば「頭を使わない」という非難だが、自分の行動に付ければ「深く考えずただ」という軽い副詞のように使う。", "vi": "“Vô” + “trí tuệ”. Hành động theo bản năng, không suy nghĩ, hoặc người như vậy. Nhắm vào người khác thì là lời chê không dùng đầu; nói về mình thì như trạng từ nhẹ nhàng “chẳng nghĩ nhiều, làm luôn”."}}]'::jsonb,
 array['뇌절','뇌지컬','알잘딱'], array[]::text[], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Mindless / without thinking"}, {"lang": "🇯🇵 JA", "text": "無知性(何も考えずに)"}, {"lang": "🇨🇳 ZH", "text": "无脑(不动脑子)"}, {"lang": "🇻🇳 VI", "text": "Không não / không suy nghĩ"}, {"lang": "🇪🇸 ES", "text": "Sin pensar / sin cerebro"}, {"lang": "🇩🇪 DE", "text": "Gedankenlos / ohne nachzudenken"}]'::jsonb),
('417', '손민수', 'new-slang', '남의 취향·물건을 그대로 따라 하는 것', NULL,
 '{"de": "Jemandes Geschmack oder Käufe nachmachen", "en": "Copying someone else''s taste or purchases", "es": "Copiar los gustos o las compras de otro", "ja": "他人の好みや持ち物をそっくり真似ること", "vi": "Bắt chước y hệt gu và đồ của người khác"}'::jsonb,
 '웹툰 《치즈인더트랩》의 등장인물 「손민수」에서 왔다. 주변 사람의 옷차림과 취향을 따라 하는 이 인물이 「어디에나 한 명쯤 있을 법한」 현실적인 캐릭터로 공감을 얻으며 이름 자체가 동사처럼 쓰이게 됐다. 처음에는 부정적인 뉘앙스가 강했으나 이후 유행·동경의 의미로 넓어졌다.',
 '{"de": "Von der Figur Son Min-su aus dem Webtoon Cheese in the Trap, die Kleidung und Vorlieben ihres Umfelds kopiert. Der Typ war so wiedererkennbar, dass der Name zum Verb wurde. Der anfangs negative Beiklang ist inzwischen eher Trendfolge und Bewunderung.", "en": "From the character Son Min-su in the webtoon Cheese in the Trap, who copies the clothes and tastes of people around her. Readers found the type painfully familiar, and the character''s name turned into a verb. The early negative edge has since softened into something closer to trend-following and admiration.", "es": "Del personaje Son Min-su del webtoon Cheese in the Trap, que copia la ropa y los gustos de quienes la rodean. El tipo resultó tan reconocible que el nombre pasó a usarse como verbo. El matiz negativo inicial se ha suavizado hacia el seguimiento de tendencias y la admiración.", "ja": "ウェブトゥーン『チーズ・イン・ザ・トラップ』の登場人物「ソン・ミンス」に由来。周囲の服装や好みを真似るこの人物が「どこにでも一人はいる」リアルな像として共感を呼び、名前そのものが動詞のように使われるようになった。当初は否定的だったが、流行追いや憧れの意味へ広がった。", "vi": "Từ nhân vật Son Min-su trong webtoon Cheese in the Trap, người bắt chước quần áo và gu của những người xung quanh. Kiểu người này quá quen thuộc nên tên nhân vật thành động từ. Sắc thái tiêu cực ban đầu đã dịu lại thành chuyện chạy theo xu hướng và ngưỡng mộ."}'::jsonb,
 '자기 행동에 붙이면 가벼운 농담이 되지만(「손민수했다」), 남을 두고 쓰면 「따라쟁이」라는 지적이 될 수 있어 사이에 따라 조심해야 한다.',
 '{"de": "Über sich selbst ein leichter Scherz; über andere schnell der Vorwurf, ein Nachmacher zu sein — also aufpassen.", "en": "About yourself it''s a light joke; about someone else it can land as calling them a copycat, so read the room.", "es": "Sobre uno mismo es una broma ligera; sobre otro puede sonar a llamarle imitador, así que ojo con el contexto.", "ja": "自分の行動に使えば軽い冗談だが、他人に使うと「真似っ子」という指摘になりうるので相手次第で注意。", "vi": "Nói về mình thì là đùa nhẹ; nói về người khác dễ thành gọi họ là kẻ bắt chước, nên tùy hoàn cảnh."}'::jsonb,
 'Son-Min-Su',
 '[{"type": "동사(이름 유래)", "examples": [{"de": "Ich hab die Tasche meiner Schwester nachgekauft.", "es": "Le copié el bolso a mi hermana y me compré el mismo.", "ja": "お姉ちゃんのバッグ、そのまま真似して買った。", "vi": "Tớ bắt chước chị mua cái túi y hệt.", "eng": "I copied my sister and bought the same bag.", "kor": "언니 가방 손민수했어."}, {"de": "Ich such gerade den Lippenstift des Schauspielers, um denselben zu kaufen.", "es": "Estoy buscando el pintalabios de ese actor para comprarme el mismo.", "ja": "あの俳優のリップを真似して買おうと検索中。", "vi": "Đang tìm son của diễn viên đó để mua theo.", "eng": "I''m looking up that actor''s lipstick so I can get the same one.", "kor": "그 배우 립스틱 손민수하려고 검색 중."}], "definition": "남의 옷차림, 화장품, 좋아하는 음식, 말투 같은 취향과 행동을 그대로 따라 하는 것. 원래는 몰래 베끼는 행동을 꼬집는 부정적인 말이었지만, 지금은 유명인이 쓰는 물건을 따라 사는 일까지 아우르며 동경에 가까운 중립·긍정 뉘앙스로 더 많이 쓴다.", "definition_i18n": {"de": "Jemandes Kleidung, Kosmetik, Essensvorlieben oder Sprechweise nachahmen. Ursprünglich ein Seitenhieb auf heimliches Kopieren, heute auch das Nachkaufen von Promi-Produkten — meist neutral bis bewundernd.", "en": "To copy someone''s clothes, cosmetics, food preferences or way of talking. It began as a dig at sneaky imitation, but now covers buying what a celebrity uses and reads mostly as neutral or admiring.", "es": "Copiar la ropa, los cosméticos, los gustos culinarios o la forma de hablar de otra persona. Empezó como pulla a la imitación disimulada, pero hoy abarca comprar lo que usa una celebridad y suena más bien neutro o admirativo.", "ja": "他人の服装、化粧品、好きな食べ物、話し方などの好みや行動をそっくり真似ること。もとはこっそり真似る行為を皮肉る否定的な語だったが、今は有名人の愛用品を追って買うことまで含み、憧れに近い中立〜肯定的なニュアンスで使われる。", "vi": "Bắt chước quần áo, mỹ phẩm, món ăn ưa thích hay cách nói của người khác. Ban đầu là lời châm chọc kiểu bắt chước lén, nay bao gồm cả việc mua theo đồ người nổi tiếng dùng và mang sắc thái trung tính hoặc ngưỡng mộ."}}]'::jsonb,
 array['최애','추구미','재질'], array['손민수하다'], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "To copy someone''s look/buys"}, {"lang": "🇯🇵 JA", "text": "真似して同じものを買う"}, {"lang": "🇨🇳 ZH", "text": "跟风模仿(同款)"}, {"lang": "🇻🇳 VI", "text": "Bắt chước mua theo"}, {"lang": "🇪🇸 ES", "text": "Copiar el look de alguien"}, {"lang": "🇩🇪 DE", "text": "Jemandem alles nachkaufen"}]'::jsonb),
('418', '킹정', 'new-slang', '완전 동의할 때 쓰는 강한 인정', NULL,
 '{"de": "Ein nachdrückliches „voll zustimmen“", "en": "An emphatic “totally agree”", "es": "Un “totalmente de acuerdo” enfático", "ja": "完全に同意するときの強い「認める」", "vi": "Câu “đồng ý hoàn toàn” nhấn mạnh"}'::jsonb,
 '특정 사건에서 나온 말이 아니라, 단어 앞에 영어 「king」을 붙여 강조하는 조어법이 유행하면서 「인정」에 붙어 생긴 말이다. 같은 계열로 「킹받다」(king+열받다)가 있다. 인터넷·SNS에서 자연 발생한 표현이라 최초 시점은 특정되지 않는다.',
 '{"de": "Kein einzelnes Ereignis als Ursprung: Es entstand aus der Mode, Wörter mit englischem „king“ zu verstärken — hier bei 인정. Verwandt ist 킹받다 (king + „sich ärgern“). Es entstand organisch im Netz, ein Erstbeleg lässt sich nicht festmachen.", "en": "Not traceable to one event: it came out of the trend of prefixing words with English “king” for emphasis, applied here to 인정. 킹받다 (king + “to get mad”) is from the same family. It arose organically online, so no first-use date can be pinned down.", "es": "No procede de un suceso concreto: nace de la moda de anteponer “king” a las palabras para enfatizar, aplicada aquí a 인정. De la misma familia es 킹받다 (king + “enfadarse”). Surgió de forma espontánea en internet, sin fecha de origen identificable.", "ja": "特定の事件由来ではなく、単語の前に英語のkingを付けて強調する造語法の流行から「認定」に付いて生まれた語。同系統に「キングパッタ(king+腹が立つ)」がある。ネット上で自然発生したため初出時期は特定できない。", "vi": "Không đến từ một sự kiện cụ thể: nó ra đời từ trào lưu thêm tiền tố “king” để nhấn mạnh, ở đây gắn vào 인정. Cùng họ có 킹받다 (king + “bực”). Nó hình thành tự nhiên trên mạng nên không xác định được mốc đầu tiên."}'::jsonb,
 '짧게 한마디로 던지는 맞장구라 채팅·댓글에서 특히 많이 쓴다. 격식 있는 자리에는 어울리지 않는다.',
 '{"de": "Eine Ein-Wort-Reaktion, vor allem in Chats und Kommentaren. Für formelle Situationen ungeeignet.", "en": "A one-word reaction, so it lives mostly in chats and comment threads. Not for formal settings.", "es": "Es una reacción de una palabra, así que vive sobre todo en chats y comentarios. No encaja en contextos formales.", "ja": "一言で返す相づちなので、チャットやコメント欄で特によく使う。フォーマルな場には向かない。", "vi": "Là câu đáp một từ nên chủ yếu dùng trong chat và bình luận. Không hợp chỗ trang trọng."}'::jsonb,
 'King-Jeong',
 '[{"type": "합성어", "examples": [{"de": "Da gibt''s das beste Tteokbokki. / Absolut, keine Widerrede.", "es": "Ese sitio tiene el mejor tteokbokki. / Totalmente de acuerdo.", "ja": "あの店のトッポッキが一番だよね。 / 完全に同意。", "vi": "Quán đó tteokbokki ngon nhất. / Chuẩn khỏi bàn.", "eng": "That place has the best tteokbokki. / Absolutely, no argument.", "kor": "그 집 떡볶이가 제일 낫지. / 킹정."}, {"de": "Montage sind echt das Letzte. / Voll unterschrieben …", "es": "Los lunes son lo peor. / Eso lo firmo…", "ja": "月曜って本当に最悪。 / それはガチで認める…", "vi": "Thứ Hai đúng là tệ nhất. / Công nhận luôn…", "eng": "Mondays really are the worst. / Facts…", "kor": "월요일 진짜 별로야. / 킹정이지…"}], "definition": "영어 「king」과 「인정」을 합친 말. 「인정」보다 한 단계 센 맞장구로, 상대 말에 완전히 동의할 때 한마디로 던진다. 앞에 king을 붙여 강조하는 「킹받다」와 같은 조어 방식이다.", "definition_i18n": {"de": "Englisch „king“ + 인정 („gebe ich zu“). Eine stärkere Form der Zustimmung, hingeworfen als „absolut, keine Widerrede“. Gleiches king--Verstärkungsmuster wie bei 킹받다.", "en": "English “king” + 인정 (“I admit it”). A stronger version of plain agreement, tossed out as a one-word “absolutely, no argument.” It uses the same king- intensifier pattern as 킹받다.", "es": "“King” en inglés + 인정 (“lo admito”). Una versión más fuerte del acuerdo simple, soltada como un “totalmente, sin discusión”. Usa el mismo prefijo intensificador king- que 킹받다.", "ja": "英語のkingと「認定(インジョン)」の合成語。ただの同意より一段強い相づちで、相手の言葉に全面的に賛成するときに一言で返す。「キング받다」と同じking-強調の造語法。", "vi": "“King” tiếng Anh + 인정 (“công nhận”). Bản mạnh hơn của lời đồng tình, ném ra như một tiếng “chuẩn khỏi bàn”. Cùng kiểu tạo từ với tiền tố king- như 킹받다."}}]'::jsonb,
 array['ㅇㅈ','킹받다','레알'], array['ㅋㅈ'], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Facts / totally agree"}, {"lang": "🇯🇵 JA", "text": "完全に同意(ガチで認める)"}, {"lang": "🇨🇳 ZH", "text": "完全同意"}, {"lang": "🇻🇳 VI", "text": "Chuẩn khỏi bàn"}, {"lang": "🇪🇸 ES", "text": "Totalmente de acuerdo"}, {"lang": "🇩🇪 DE", "text": "Voll unterschrieben"}]'::jsonb),
('419', '국뽕', 'new-slang', '자기 나라에 취한 듯한 과한 자부심', NULL,
 '{"de": "Berauscht vom Nationalstolz", "en": "Being high on national pride", "es": "Estar drogado de orgullo nacional", "ja": "自国に酔ったような過剰な誇り", "vi": "Say sưa tự hào dân tộc quá đà"}'::jsonb,
 '「국가」+「히로뽕」의 합성어. 디시인사이드 역사 갤러리에서 나왔다고 보는 시각이 강하지만 확정된 것은 아니다. 2013년 월드 베이스볼 클래식에서 한국 선수들이 활약하자 국내야구 갤러리를 중심으로 「국뽕」 드립이 쏟아지며 본격적으로 유행했다. 처음에는 비뚤어진 애국심을 조롱하는 말이었으나 쓰임이 늘며 애국심 전반을 가리키는 중립적 표현으로도 확장됐다.',
 '{"de": "Eine Mischung aus „Nation“ und „Philopon“. Häufig wird DC Insides Geschichtsboard als Ursprung vermutet, bestätigt ist das nicht. Populär wurde es 2013, als Koreas Auftritt beim World Baseball Classic eine Welle von 국뽕-Witzen auslöste. Aus dem Spott über verzerrten Patriotismus wurde ein recht neutraler Begriff für Nationalstolz.", "en": "A blend of “nation” and “philopon.” It is widely believed to have started on DC Inside''s history board, though that is not confirmed. It took off in 2013 when Korea''s run at the World Baseball Classic set off a wave of 국뽕 jokes on the baseball board. Originally a jab at distorted patriotism, it has broadened into a fairly neutral term for national pride in general.", "es": "Mezcla de “nación” y “filopón”. Se cree que surgió en el foro de historia de DC Inside, aunque no está confirmado. Despegó en 2013, cuando la actuación de Corea en el Clásico Mundial de Béisbol desató una oleada de bromas de 국뽕. De burla al patriotismo torcido pasó a ser un término bastante neutro para el orgullo nacional.", "ja": "「国家」と「ヒロポン」の合成語。DCインサイドの歴史ギャラリー発とみる見方が強いが未確定。2013年のワールド・ベースボール・クラシックで韓国代表が活躍し、野球ギャラリーを中心に「クッポン」ネタが溢れて本格的に流行した。当初は歪んだ愛国心への嘲りだったが、今では愛国心全般を指す中立的な語にも広がった。", "vi": "Ghép “quốc gia” với “philopon”. Nhiều người cho rằng nó khởi từ chuyên mục lịch sử của DC Inside, nhưng chưa xác nhận. Nó bùng lên năm 2013 khi tuyển Hàn thi đấu tốt ở World Baseball Classic, kéo theo làn sóng đùa 국뽕. Từ chỗ mỉa lòng ái quốc lệch lạc, nay nó khá trung tính, chỉ niềm tự hào dân tộc nói chung."}'::jsonb,
 '자기 감정에 붙이면 자조 섞인 농담이 되고(「국뽕 차오른다」), 남에게 붙이면 「과하다」는 비판이 된다. 「국뽕 빼고」는 감정을 걷어내고 객관적으로 보자는 뜻으로 자주 쓴다.',
 '{"de": "Auf sich selbst gemünzt ist es ein selbstironischer Scherz („der Stolz steigt“), auf andere gemünzt Kritik am Übertreiben. Die Wendung 국뽕 빼고 („Patriotismus beiseite“) heißt: objektiv betrachtet.", "en": "Applied to yourself it''s a self-aware joke (“the pride is rising”); applied to others it''s a criticism of going overboard. The phrase 국뽕 빼고 (“patriotism aside”) is common for “let''s look at it objectively.”", "es": "Sobre uno mismo es una broma autoconsciente (“me sube el orgullo”); sobre otros, una crítica por pasarse. La fórmula 국뽕 빼고 (“sin el patriotismo”) se usa mucho para “veámoslo con objetividad”.", "ja": "自分の感情に使えば自嘲混じりの冗談になり(「愛国心こみ上げる」)、他人に使うと「やりすぎ」という批判になる。「クッポン抜きで」は感情を除いて客観的に見ようという意味でよく使う。", "vi": "Nói về mình thì là đùa tự giễu (“tự hào dâng trào”); nói về người khác thành lời chê quá đà. Cụm 국뽕 빼고 (“bỏ qua tự hào dân tộc”) hay dùng với nghĩa “nhìn khách quan đi”."}'::jsonb,
 'Guk-Ppong',
 '[{"type": "합성어", "examples": [{"de": "Diese Doku pusht den Nationalstolz ganz schön, oder?", "es": "Este documental me está subiendo el orgullo patrio, ¿eh?", "ja": "このドキュメンタリー、ちょっと愛国心こみ上げるんだけど?", "vi": "Phim tài liệu này làm dâng cả niềm tự hào dân tộc luôn.", "eng": "This documentary is really pumping up the national pride, huh?", "kor": "이 다큐 국뽕 좀 차오르는데?"}, {"de": "Auch ohne Nationalstolz war das Spiel wirklich stark.", "es": "Incluso quitando el orgullo patrio, ese partido estuvo genial.", "ja": "愛国心を抜きにしても、今回の試合は本当に良かった。", "vi": "Bỏ qua chuyện tự hào dân tộc thì trận này đá thật sự hay.", "eng": "Even setting the patriotism aside, that was genuinely a great match.", "kor": "국뽕 빼고 봐도 이번 경기는 진짜 잘했어."}], "definition": "「국가」와 마약 히로뽕의 「뽕」을 합친 말. 자기 나라에 도취돼 과하게 찬양하는 태도를 비꼬는 데서 출발했다. 지금은 스포츠·문화 성과에 벅차오르는 애국심 전반이나, 그런 감정을 노리고 만든 콘텐츠를 가리키는 데까지 넓게 쓴다.", "definition_i18n": {"de": "„Nation“ plus das -ppong von Philopon (Crystal Meth). Zunächst Spott über berauschten, übertriebenen Patriotismus; heute auch der Stolz bei Sport- oder Kulturerfolgen und Inhalte, die genau darauf abzielen.", "en": "“Nation” + the -ppong of philopon (meth). It started as mockery of intoxicated, over-the-top patriotism; today it also covers the swell of pride at sporting or cultural wins, and content deliberately engineered to trigger it.", "es": "“Nación” + el -ppong de filopón (metanfetamina). Nació como burla del patriotismo desmedido y embriagado; hoy abarca también la emoción por logros deportivos o culturales y el contenido hecho a propósito para provocarla.", "ja": "「国家」と覚醒剤ヒロポンの「ポン」の合成語。自国に酔った過剰な称賛を皮肉る言葉として始まり、今ではスポーツや文化の成果に込み上げる愛国心全般や、それを狙って作られたコンテンツも指す。", "vi": "“Quốc gia” + phần -ppong của philopon (ma túy đá). Ban đầu là lời mỉa lòng ái quốc thái quá như say thuốc; nay còn chỉ niềm tự hào dâng trào trước thành tích thể thao, văn hóa và cả nội dung cố tình tạo ra cảm xúc đó."}}]'::jsonb,
 array['과몰입','억텐','떡상'], array[]::text[], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "High on national pride"}, {"lang": "🇯🇵 JA", "text": "過剰な愛国心(愛国酔い)"}, {"lang": "🇨🇳 ZH", "text": "民族自豪感上头"}, {"lang": "🇻🇳 VI", "text": "Say tự hào dân tộc"}, {"lang": "🇪🇸 ES", "text": "Subidón de orgullo patrio"}, {"lang": "🇩🇪 DE", "text": "Patriotismus-Rausch"}]'::jsonb),
('420', '드렁슨', 'new-slang', '코 골며 자는 모습을 귀엽게 이르는 말', '[드렁슨]',
 '{"de": "Ein niedliches Wort fürs Schnarchen", "en": "A cutesy word for snoring away", "es": "Palabra tierna para roncar a pierna suelta", "ja": "いびきをかいて寝ている様子をかわいく言う語", "vi": "Từ dễ thương chỉ việc ngáy khò khò"}'::jsonb,
 '의성어에 ‘-슨’을 붙여 사람 이름처럼 만드는 Z세대 조어 놀이의 하나로, ‘쿨쿨슨’(곤히 자는 것), ‘엉엉슨’(우는 것) 등과 같은 계열이다. 이 계열이 언제 누구에게서 시작됐는지는 확인되지 않는다.',
 '{"de": "Gehört zu einer Familie von Gen-Z-Wortschöpfungen, die Lautmalerei per -seun zum Fake-Nachnamen machen, neben 쿨쿨슨 (fest schlafen) und 엉엉슨 (weinen). Woher und von wem das Muster stammt, ist unbelegt.", "en": "One of a family of Gen Z coinages that turn onomatopoeia into a fake surname with -seun, alongside 쿨쿨슨 (sleeping soundly) and 엉엉슨 (crying). Where the pattern started, and with whom, is unverified.", "es": "Pertenece a una familia de invenciones de la generación Z que convierten onomatopeyas en apellidos falsos con -seun, junto a 쿨쿨슨 (dormir profundamente) y 엉엉슨 (llorar). No se ha verificado dónde ni con quién empezó el patrón.", "ja": "擬音語に「-スン」を付けて人名風にするZ世代の造語遊びの一つで、「クルクルスン(ぐっすり寝る)」「オンオンスン(泣く)」などと同系列。この系列の初出は未確認。", "vi": "Thuộc nhóm từ do Gen Z chế ra bằng cách gắn -seun vào từ tượng thanh cho giống họ người, cùng với 쿨쿨슨 (ngủ say) và 엉엉슨 (khóc). Không rõ kiểu đặt từ này bắt đầu từ đâu, từ ai."}'::jsonb,
 'SNS·릴스에서 자는 사람 영상 캡션으로 쓰거나, 가족이 코 고는 걸 놀리듯 애정 섞어 말할 때 쓴다. 낯선 사람에게 쓰면 무례할 수 있다.',
 '{"de": "Als Caption unter Videos von Schlafenden oder um das Schnarchen von Familienmitgliedern liebevoll aufzuziehen. Bei Fremden kann es unhöflich wirken.", "en": "Used as a caption on videos of someone sleeping, or to tease a family member’s snoring with affection. It can be rude toward strangers.", "es": "Se usa como pie de foto en vídeos de alguien durmiendo, o para picar con cariño el ronquido de un familiar. Con desconocidos puede resultar grosero.", "ja": "SNSやリールで寝ている人の動画のキャプションに使ったり、家族のいびきを愛情込めてからかうときに使う。他人に使うと失礼になりうる。", "vi": "Dùng làm caption cho video ai đó đang ngủ, hoặc trêu tiếng ngáy của người nhà một cách trìu mến. Dùng với người lạ có thể bất lịch sự."}'::jsonb,
 'Deu-Reong-Seun',
 '[{"type": "명사", "examples": [{"de": "Papa liegt auf dem Sofa und schnarcht vor sich hin hahaha.", "es": "Papá está en el sofá roncando a lo grande jajaja.", "ja": "パパ、ソファでドゥロンスン中www", "vi": "Bố đang ngáy khò trên sofa haha.", "eng": "Dad is on the couch doing his snore-son thing lol.", "kor": "아빠 소파에서 드렁슨 중 ㅋㅋㅋ"}, {"de": "Anscheinend hab ich gestern vor Müdigkeit geschnarcht. Wie peinlich …", "es": "Al parecer anoche ronqué muchísimo de lo cansada que estaba. Qué vergüenza…", "ja": "昨日疲れすぎていびきかいてたらしい。恥ずかしい…", "vi": "Nghe bảo tối qua mình mệt quá nên ngáy ầm ĩ. Ngại ghê…", "eng": "Apparently I was snoring like crazy last night, I was that tired. So embarrassing…", "kor": "나 어제 너무 피곤해서 드렁슨했대. 창피해…"}], "definition": "코 고는 소리 ‘드르렁’에 사람 이름처럼 들리는 접미사 ‘-슨’을 붙인 말. 코를 골며 곤히 자는 모습이나 그 소리를 귀엽고 유쾌하게 가리킨다.", "definition_i18n": {"de": "Das Schnarchgeräusch 드르렁 plus das namensartige Suffix -seun. Es bezeichnet liebevoll-komisch jemanden, der schnarchend tief schläft, oder das Geräusch selbst.", "en": "The snoring sound 드르렁 plus the name-like suffix -seun. It refers, fondly and comically, to someone fast asleep and snoring, or to the sound itself.", "es": "El sonido de ronquido 드르렁 más el sufijo -seun, que suena a apellido. Designa con cariño y humor a quien duerme roncando, o al ronquido mismo.", "ja": "いびきの音「ドゥルロン」に人名っぽい接尾辞「-スン」を付けた語。いびきをかいてぐっすり眠る様子やその音を、かわいく愉快に指す。", "vi": "Tiếng ngáy 드르렁 cộng hậu tố -seun nghe như tên người. Chỉ một cách trìu mến, hài hước cảnh ai đó ngủ say ngáy khò, hoặc chính tiếng ngáy đó."}}]'::jsonb,
 array['밈','짤','갓생'], array[]::text[], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Snoring away / Mr. Snore"}, {"lang": "🇯🇵 JA", "text": "いびきスン(グーグー寝)"}, {"lang": "🇨🇳 ZH", "text": "呼噜噜(打呼睡觉)"}, {"lang": "🇻🇳 VI", "text": "Ngáy khò khò"}, {"lang": "🇪🇸 ES", "text": "Roncando (don Ronquido)"}, {"lang": "🇩🇪 DE", "text": "Schnarch-Sohn"}]'::jsonb),
('421', '위고빔', 'new-slang', '운동은 안 하고 살 빠지기만 바라는 것', '[위고빔]',
 '{"en": "Wishing the weight off without doing anything about it", "ja": "運動はせずやせることだけ願うこと", "es": "Querer adelgazar sin mover un dedo", "vi": "Chỉ mong giảm cân mà chẳng làm gì", "de": "Abnehmen wollen, ohne irgendetwas dafür zu tun"}'::jsonb,
 '다이어트 주사 「위고비(Wegovy)」와 만화에서 광선을 쏠 때의 「빔」을 합친 말. 유튜브 채널 《빠더너스》의 문상훈이 2025년 「올해 유행할 신조어 예측」 영상에서 직접 만들어 소개한 말이 밈으로 퍼졌다. 자연 발생한 유행어가 아니라 창작 신조어라는 점이 특이하다.',
 '{"en": "Wegovy (the weight-loss injection) blended with \"beam\", the comic-book energy ray. Comedian Mun Sang-hun coined it in a 2025 video on his YouTube channel 빠더너스 predicting the year''s neologisms, and it spread as a meme — unusually, an invented word rather than one that arose on its own.", "ja": "ダイエット注射「ウゴービ(Wegovy)」と、漫画で光線を撃つときの「ビーム」を合わせた語。YouTubeチャンネル『パダノス』の文相勲が2025年の「今年流行る新語予測」動画で自ら作って紹介し、ミームとして広まった。自然発生ではなく創作された新語という点が珍しい。", "es": "Mezcla de Wegovy (la inyección para adelgazar) y \"beam\", el rayo de los cómics. El cómico Mun Sang-hun lo inventó en 2025 en un vídeo de su canal 빠더너스 sobre los neologismos del año, y se difundió como meme — curiosamente, una palabra inventada, no surgida sola.", "vi": "Ghép từ Wegovy (mũi tiêm giảm cân) và \"beam\" — tia sáng trong truyện tranh. Danh hài Mun Sang-hun nghĩ ra trong video năm 2025 trên kênh YouTube 빠더너스 dự đoán từ mới của năm, rồi lan thành meme — lạ ở chỗ đây là từ được sáng tác chứ không tự phát sinh.", "de": "Aus „Wegovy“ (Abnehmspritze) und „Beam“ (der Comic-Strahl). Der Komiker Mun Sang-hun erfand es 2025 in einem Video seines YouTube-Kanals 빠더너스 über „Neologismen, die dieses Jahr angesagt werden“ — von dort verbreitete es sich als Meme. Ungewöhnlich: ein erfundenes, kein natürlich entstandenes Wort."}'::jsonb,
 '친구끼리 농담으로 쓴다. 「위고빔 맞고 있어」처럼 주사를 맞는다는 말투로 쓰는 게 정석. 실제 위고비 처방 이야기와 헷갈릴 수 있으니 농담인 게 분명한 자리에서만 쓴다.',
 '{"en": "A joke between friends. The standard phrasing is \"I''m on Wigobim\", as if getting the injection. Use it only where the joke is obvious, or it gets confused with an actual Wegovy prescription.", "ja": "友達同士の冗談として使う。「위고빔 맞고 있어(ウィゴビーム打ってる)」のように注射を打つ言い方が定番。実際のウゴービ処方の話と紛らわしいので、冗談だと分かる場でだけ使う。", "es": "Broma entre amigos. La forma típica es \"me estoy poniendo wigobim\", como si fuera la inyección. Úsalo solo donde quede claro que es broma, o se confunde con un tratamiento real.", "vi": "Câu đùa giữa bạn bè. Cách nói chuẩn là \"tớ đang tiêm wigobim\", như thể đi chích thật. Chỉ dùng khi rõ ràng là đùa, kẻo lẫn với chuyện dùng Wegovy thật.", "de": "Ein Scherz unter Freunden. Standardform: „Ich bin gerade auf Wigobim“ — als bekäme man eine Spritze. Nur dort verwenden, wo klar ist, dass es Spaß ist, sonst wird es mit echter Wegovy-Behandlung verwechselt."}'::jsonb,
 'Wigobim',
 '[{"type": "명사", "definition": "운동도 식단 관리도 하지 않으면서 살이 빠지기만 간절히 바라는 것. 다이어트 주사를 맞는 대신 마음속으로 「제발 빠져라」 하고 비는 상태를 주사 맞는 것처럼 익살스럽게 말한다.", "definition_i18n": {"en": "Desperately hoping to lose weight while doing no exercise and watching no diet — the joke frames pure wishful thinking as if it were an injection you get.", "ja": "運動も食事管理もせず、ただ「やせますように」と願うだけの状態。何もしていないのに注射を打っているかのように言うのが笑いどころ。", "es": "Desear adelgazar sin hacer ejercicio ni dieta — la gracia está en hablar del puro deseo como si fuera una inyección que te pones.", "vi": "Chỉ khao khát giảm cân mà không tập cũng không kiêng — cái hài là nói về ước muốn suông như thể đang đi tiêm thuốc.", "de": "Abnehmen wollen, ohne Sport oder Diät — nur inständig hoffen. Der Witz: Man tut so, als bekäme man eine Spritze, während man in Wahrheit bloß betet."}, "examples": [{"kor": "야 너 다이어트 한다며, 운동 안 해? / 나 요즘 위고빔 맞고 있어… 빠지게 해주세요 🙏", "eng": "Weren''t you on a diet? Not working out? / I''m on Wigobim these days… please let it come off 🙏", "ja": "ダイエットするって言ってなかった?運動は? / 最近ウィゴビーム打ってる…やせますように🙏", "es": "¿No estabas a dieta? ¿No entrenas? / Últimamente me pongo wigobim… que se me vaya, porfa 🙏", "vi": "Bảo giảm cân mà không tập à? / Dạo này tớ tiêm wigobim… cho gầy đi với 🙏", "de": "Wolltest du nicht abnehmen? Kein Sport? / Ich bin zurzeit auf Wigobim … bitte lass es purzeln 🙏"}]}]'::jsonb,
 array[]::text[], array[]::text[], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Wishing the weight off, doing nothing"}, {"lang": "🇯🇵 JA", "text": "何もせずやせるのを願うだけ"}, {"lang": "🇨🇳 ZH", "text": "什么都不做只盼着瘦"}, {"lang": "🇻🇳 VI", "text": "Không làm gì, chỉ mong gầy"}, {"lang": "🇪🇸 ES", "text": "Adelgazar a base de deseo"}, {"lang": "🇩🇪 DE", "text": "Abnehmen nur per Wunschdenken"}]'::jsonb),
('422', '진지스칸', 'new-slang', '혼자 진지해져서 분위기를 깨는 사람', '[진지스칸]',
 '{"de": "Wer bierernst wird und die Stimmung killt", "en": "The one who goes dead serious and kills the vibe", "es": "El que se pone serio y mata el ambiente", "ja": "一人だけ真剣になって場をしらけさせる人", "vi": "Người tự nhiên nghiêm túc làm tụt hết không khí"}'::jsonb,
 '‘진지’에 칭기즈 칸(Genghis Khan)의 이름을 붙인 언어유희로 설명된다. 분위기를 단숨에 제압한다는 점을 칸의 정복에 빗댄 것이라는 해석이 있으나, 누가 언제 처음 썼는지는 확인되지 않는다.',
 '{"de": "Gilt als Wortspiel, das Dschingis Khan auf 진지 (ernst) pfropft. Manche lesen das Eroberungsbild als „die Stimmung in einem Zug plattwalzen“, doch Urheber und Zeitpunkt sind unbelegt.", "en": "Explained as a pun grafting Genghis Khan onto 진지 (serious). Some read the conquest imagery as “flattening the mood in one stroke,” but who coined it and when is unverified.", "es": "Se explica como un juego de palabras que injerta a Gengis Kan en 진지 (serio). Hay quien lee la imagen conquistadora como “arrasar el ambiente de un golpe”, pero no se sabe quién lo acuñó ni cuándo.", "ja": "「진지(真剣)」にチンギス・カンの名を重ねた言葉遊びとされる。場を一気に制圧する様子を征服になぞらえた、という解釈もあるが、初出は未確認。", "vi": "Được giải thích là lối chơi chữ ghép Thành Cát Tư Hãn vào 진지 (nghiêm túc). Có cách hiểu rằng hình ảnh chinh phạt ám chỉ “dẹp không khí trong một nốt nhạc”, nhưng ai đặt ra và khi nào thì chưa rõ."}'::jsonb,
 '놀리는 뉘앙스가 분명해 친한 사이에서만 쓴다. 상대가 실제로 진지한 이야기를 꺼낸 상황에 쓰면 무례하게 들린다.',
 '{"de": "Deutlich neckend, also nur unter engen Freunden. Wenn jemand ein wirklich ernstes Thema anspricht, wirkt es unhöflich.", "en": "Clearly teasing, so keep it among close friends. Using it when someone raises a genuinely serious topic comes off as rude.", "es": "Es claramente burlón, así que úsalo solo entre amigos. Si alguien saca un tema de verdad serio, suena grosero.", "ja": "からかいのニュアンスが明確なので親しい間柄限定。相手が本当に真剣な話をしている場面で使うと失礼に聞こえる。", "vi": "Rõ ràng mang ý trêu chọc nên chỉ dùng với bạn thân. Nếu người ta đang nói chuyện nghiêm túc thật mà dùng thì nghe rất vô duyên."}'::jsonb,
 'Jin-Ji-Seu-Kan',
 '[{"type": "명사", "examples": [{"de": "War doch nur ein Witz — werd jetzt nicht zum Dschingis Ernst haha.", "es": "Tío, era solo una broma, no te pongas en modo Jinjis Kan jaja.", "ja": "それただの冗談だって、真剣カンになるなよw", "vi": "Đùa thôi mà, đừng có làm Thành Cát Tư Nghiêm nha haha.", "eng": "Dude, it was just a joke — do not go full Jinjis Khan lol.", "kor": "야 그거 그냥 농담인데, 진지스칸 되지 마 ㅋㅋ"}, {"de": "Ein Dschingis Ernst im Gruppenchat und das Gespräch ist tot.", "es": "Basta un Jinjis Kan en el grupo para que la conversación muera.", "ja": "グループチャットに真剣カンが一人いると会話が終わる。", "vi": "Nhóm chat có một Thành Cát Tư Nghiêm là đứt cuộc trò chuyện.", "eng": "One Jinjis Khan in the group chat and the conversation is over.", "kor": "단톡방에 진지스칸 한 명 있으면 대화 끝난다."}], "definition": "‘진지하다’와 몽골 제국의 ‘칭기즈 칸’을 합친 말장난. 농담이 오가는 자리에서 혼자 정색하고 진지하게 반응해 분위기를 가라앉히는 사람을 놀릴 때 쓴다.", "definition_i18n": {"de": "Ein Wortspiel aus 진지하다 (ernst sein) und Dschingis Khan. Es zieht die Person auf, die mitten im Spaß todernst reagiert und die Stimmung plattmacht.", "en": "A pun on 진지하다 (to be serious) and Genghis Khan. It teases the person who reacts with total seriousness in the middle of a joking conversation and flattens the mood.", "es": "Juego de palabras entre 진지하다 (ser serio) y Gengis Kan. Se burla de quien reacciona con total seriedad en plena broma y aplasta el ambiente.", "ja": "「真剣だ(진지하다)」とチンギス・カンを掛けた言葉遊び。冗談が飛び交う場で一人だけ真顔で反応し、場をしらけさせる人をからかう言葉。", "vi": "Chơi chữ giữa 진지하다 (nghiêm túc) và Thành Cát Tư Hãn. Dùng để trêu người phản ứng cực kỳ nghiêm túc giữa lúc mọi người đang đùa, làm xẹp không khí."}}]'::jsonb,
 array['씹선비','뇌절','갑분싸'], array[]::text[], 0, 0,
 '[{"lang": "🇺🇸 EN", "text": "Buzzkill / Mr. Serious"}, {"lang": "🇯🇵 JA", "text": "空気読めない真面目キャラ"}, {"lang": "🇨🇳 ZH", "text": "扫兴的认真人"}, {"lang": "🇻🇳 VI", "text": "Người phá không khí vì quá nghiêm túc"}, {"lang": "🇪🇸 ES", "text": "Aguafiestas serio"}, {"lang": "🇩🇪 DE", "text": "Spaßbremse"}]'::jsonb);

